import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, Send, X, Bot, User, Loader2, Minimize2 } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { Button } from './UiElements';
import { CONTACT_INFO, SERVICES, PRICING_DATA } from '../constants';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: "Bonjour ! Je suis l'assistant intelligent de WinCore. Comment puis-je vous aider dans vos projets informatiques aujourd'hui ?" }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const systemInstruction = `
        Tu es l'assistant IA officiel de WinCore Tech, une entreprise informatique dirigée par Zadeck Hexmoor à Cotonou, Bénin.
        Ton rôle est de renseigner les clients sur nos services et produits avec expertise et courtoisie.

        SERVICES : ${SERVICES.map(s => s.title).join(', ')}.
        TARIFS : ${PRICING_DATA.map(p => `${p.service}: ${p.priceFCFA}`).join(' | ')}.
        CONTACT : WhatsApp/Tel: ${CONTACT_INFO.phone}, Email: ${CONTACT_INFO.email}.
        LOCALISATION : ${CONTACT_INFO.location}.

        CONSIGNES :
        1. Sois professionnel, technologique et concis.
        2. Encourage toujours à contacter Zadeck Hexmoor via WhatsApp pour finaliser une commande.
        3. Réponds en français.
        4. Si un utilisateur demande une remise, explique que nos tarifs sont déjà optimisés pour la qualité Premium fournie.
        5. WinCore est spécialisé en installation Windows, Pack Office, Logiciels Pro (Adobe/AutoCAD), Déblocage Mobile (FRP/iCloud) et Création Web.
      `;

      const chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
        config: {
          systemInstruction: systemInstruction,
          temperature: 0.7,
        },
        history: messages.map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        }))
      });

      const result = await chat.sendMessage({ message: userMessage });
      const responseText = result.text;

      setMessages(prev => [...prev, { role: 'model', text: responseText || "Désolé, j'ai rencontré une petite erreur technique. Pouvez-vous reformuler ?" }]);
    } catch (error) {
      console.error("Chat Error:", error);
      setMessages(prev => [...prev, { role: 'model', text: "Je suis temporairement hors ligne. N'hésitez pas à nous contacter directement sur WhatsApp !" }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Toggle Button */}
      <button 
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-6 left-6 z-50 p-4 rounded-full bg-[#00A4FF] text-white shadow-lg transition-all duration-500 hover:scale-110 group ${isOpen ? 'scale-0 opacity-0' : 'scale-100 opacity-100'}`}
        aria-label="Ouvrir le chat IA"
      >
        <div className="absolute inset-0 rounded-full bg-[#00A4FF] animate-ping opacity-20"></div>
        <MessageSquare className="w-6 h-6 group-hover:rotate-12 transition-transform" />
        <span className="absolute -top-12 left-0 bg-white text-black text-[10px] font-bold px-2 py-1 rounded whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity">
          Assistant WinCore AI
        </span>
      </button>

      {/* Chat Window */}
      <div className={`fixed bottom-6 left-6 z-[60] w-[90vw] md:w-[400px] h-[550px] max-h-[80vh] flex flex-col glass-panel border border-white/20 shadow-2xl transition-all duration-500 origin-bottom-left ${isOpen ? 'scale-100 opacity-100' : 'scale-0 opacity-0 pointer-events-none'}`}>

        {/* Header */}
        <div className="p-4 border-b border-white/10 flex items-center justify-between bg-gradient-to-r from-[#00A4FF]/20 to-[#FF00C8]/20 rounded-t-2xl">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-[#06070A] border border-[#00A4FF]/50 flex items-center justify-center">
              <Bot className="w-6 h-6 text-[#00A4FF]" />
            </div>
            <div>
              <h3 className="text-white font-bold text-sm">WinCore AI</h3>
              <div className="flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-[#00FF9D] animate-pulse"></span>
                <span className="text-[10px] text-[#C8D1D8]">En ligne - Expert Digital</span>
              </div>
            </div>
          </div>
          <button onClick={() => setIsOpen(false)} className="text-[#C8D1D8] hover:text-white transition-colors">
            <Minimize2 className="w-5 h-5" />
          </button>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in-up`}>
              <div className={`max-w-[85%] flex gap-2 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                <div className={`w-8 h-8 rounded-full shrink-0 flex items-center justify-center ${m.role === 'user' ? 'bg-[#00A4FF]/20 text-[#00A4FF]' : 'bg-[#FF00C8]/20 text-[#FF00C8]'}`}>
                  {m.role === 'user' ? <User className="w-4 h-4" /> : <Bot className="w-4 h-4" />}
                </div>
                <div className={`p-3 rounded-2xl text-sm leading-relaxed ${
                  m.role === 'user' 
                    ? 'bg-[#00A4FF] text-white rounded-tr-none' 
                    : 'bg-white/5 border border-white/10 text-[#C8D1D8] rounded-tl-none'
                }`}>
                  {m.text}
                </div>
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start animate-pulse">
              <div className="flex gap-2 items-center bg-white/5 border border-white/10 p-3 rounded-2xl rounded-tl-none">
                <Loader2 className="w-4 h-4 text-[#00A4FF] animate-spin" />
                <span className="text-xs text-[#C8D1D8]">WinCore AI réfléchit...</span>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 border-t border-white/10 bg-black/40 rounded-b-2xl">
          <div className="relative flex items-center">
            <input 
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Posez votre question..."
              className="w-full bg-white/5 border border-white/10 rounded-full py-3 pl-4 pr-12 text-sm text-white focus:outline-none focus:border-[#00A4FF] transition-colors"
            />
            <button 
              onClick={handleSend}
              disabled={isLoading || !input.trim()}
              className="absolute right-2 p-2 bg-[#00A4FF] text-white rounded-full disabled:opacity-50 disabled:cursor-not-allowed hover:bg-[#0094e6] transition-colors"
            >
              <Send className="w-4 h-4" />
            </button>
          </div>
          <p className="text-[9px] text-center text-gray-500 mt-2">
            Propulsé par Gemini 3 Pro Preview - Services WinCore 2025
          </p>
        </div>
      </div>
    </>
  );
};

export default ChatBot;

