  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (href: string) => {
    setIsMobileMenuOpen(false);
    const element = document.querySelector(href);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header 
      className={`fixed top-0 w-full z-50 transition-all duration-500 ${
        isScrolled ? 'bg-[#06070A]/95 backdrop-blur-xl border-b border-white/10 py-2 shadow-2xl' : 'bg-transparent py-5'
      }`}
    >
      <div className="container mx-auto px-4 flex justify-between items-center">
        {/* Logo clickable area */}
        <div className="flex items-center cursor-pointer py-1" onClick={() => scrollToSection('#hero')}>
            <WinCoreLogo />
        </div>

        {/* Desktop Nav */}
        <nav className="hidden lg:flex items-center gap-8">
          {NAV_LINKS.map((link) => (
            <button 
              key={link.label}
              onClick={() => scrollToSection(link.href)}
              className="text-xs font-bold text-[#C8D1D8] hover:text-[#FF8A00] transition-colors uppercase tracking-[0.2em] relative group"
            >
              {link.label}
              <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-gradient-to-r from-[#FF8A00] to-[#FF00C8] transition-all duration-300 group-hover:w-full"></span>
            </button>
          ))}
          <Button onClick={() => scrollToSection('#contact')} variant="primary" className="py-2.5 px-6 text-xs uppercase tracking-widest" glow>
            Commander
          </Button>
        </nav>

        {/* Mobile Toggle */}
        <button 
          className="lg:hidden text-white p-2 hover:bg-white/10 rounded-lg transition-colors"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="lg:hidden absolute top-full left-0 w-full bg-[#06070A] border-b border-white/10 shadow-2xl animate-fade-in-up">
          <div className="flex flex-col p-6 gap-4">
            {NAV_LINKS.map((link) => (
              <button 
                key={link.label}
                onClick={() => scrollToSection(link.href)}
                className="text-left text-[#C8D1D8] hover:text-[#FF8A00] py-4 border-b border-white/5 text-sm font-bold uppercase tracking-widest flex justify-between items-center group"
              >
                {link.label}
                <span className="w-2 h-2 rounded-full bg-[#FF8A00] opacity-0 group-hover:opacity-100 transition-opacity shadow-[0_0_10px_#FF8A00]"></span>
              </button>
            ))}
            <Button onClick={() => scrollToSection('#contact')} className="mt-4 w-full text-sm uppercase tracking-widest py-4">
              Commander maintenant
            </Button>
          </div>
        </div>
      )}
    </header>
  );
};

